<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
final class ContractRenewalService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit) {}
    private function terms(array $c):array {return array_intersect_key($c,array_flip(['contract_id','client_id','contract_number','contract_name','start_date','end_date','monthly_value','required_guard_count','shift_requirements_json','status']));}
    private function fingerprint(array $c):string {$v=$this->terms($c);ksort($v);return hash('sha256',json_encode($v,JSON_THROW_ON_ERROR));}
    private function offerIntact(array $r):bool {return hash_equals($r['offer_hash'],hash('sha256',json_encode([$r['base_hash'],$r['starts_on'],$r['ends_on'],(int)$r['monthly_minor'],$r['currency'],$r['terms']],JSON_THROW_ON_ERROR)));}
    private function mapped(mixed $client):void {if(!$this->db->fetch('SELECT client_id FROM client_portal_access WHERE company_id=:company AND client_id=:client AND user_id=:actor',['company'=>$this->company(),'client'=>$client,'actor'=>$this->actor()]))throw HttpException::notFound();}
    public function list(bool $client=false):array {$rows=$this->db->fetchAll('SELECT r.* FROM contract_renewals r JOIN contracts c ON c.company_id=r.company_id AND c.contract_id=r.contract_id AND c.client_id=r.client_id WHERE r.company_id=:company AND c.deleted_at IS NULL'.($client?' AND EXISTS(SELECT 1 FROM client_portal_access a WHERE a.company_id=r.company_id AND a.client_id=r.client_id AND a.user_id=:actor)':'').' ORDER BY renewal_id DESC LIMIT 200',$client?['company'=>$this->company(),'actor'=>$this->actor()]:['company'=>$this->company()]);foreach($rows as&$r){unset($r['base_json']);$r['history']=$this->db->fetchAll('SELECT before_json,after_json,applied_at FROM contract_term_history WHERE company_id=:company AND renewal_id=:renewal',['company'=>$this->company(),'renewal'=>$r['renewal_id']]);}unset($r);return $rows;}
    public function propose(array $input):array {return $this->atomic(function()use($input){$this->fields($input,['contract_id','starts_on','ends_on','monthly_minor','currency','terms']);$c=$this->row('contracts','contract_id',$input['contract_id']??null);if(!empty($c['deleted_at'])||!in_array($c['status'],['ACTIVE','EXPIRED'],true))throw HttpException::conflict('Choose an active or expired contract.');$from=$this->day($input['starts_on']??null);$to=$this->day($input['ends_on']??null);$currency=$input['currency']??null;if($from<gmdate('Y-m-d')||$to<=$from||($c['end_date']!==null&&$from<=$c['end_date'])||strtotime($to.' UTC')-strtotime($from.' UTC')>5*366*86400||!in_array($currency,['ZAR','USD','EUR','GBP','NAD','BWP'],true))throw HttpException::unprocessable('Choose a future renewal after the existing term, lasting at most five years, and a supported currency.');if($this->db->fetch("SELECT renewal_id FROM contract_renewals WHERE company_id=:company AND contract_id=:contract AND state IN ('SHARED','ACCEPTED','SCHEDULED')",['company'=>$this->company(),'contract'=>$c['contract_id']]))throw HttpException::conflict('A renewal is already awaiting decision or application.');$price=$this->number($input['monthly_minor']??null,0,1000000000);$terms=$this->text($input['terms']??null,10000);$base=$this->fingerprint($c);$hash=hash('sha256',json_encode([$base,$from,$to,$price,$currency,$terms],JSON_THROW_ON_ERROR));$this->db->execute('INSERT INTO contract_renewals(company_id,contract_id,client_id,base_hash,base_json,starts_on,ends_on,monthly_minor,currency,terms,offer_hash,created_by_user_id,created_at) VALUES(:company,:contract,:client,:base,:json,:start,:end,:price,:currency,:terms,:hash,:actor,:now)',['company'=>$this->company(),'contract'=>$c['contract_id'],'client'=>$c['client_id'],'base'=>$base,'json'=>json_encode($this->terms($c),JSON_THROW_ON_ERROR),'start'=>$from,'end'=>$to,'price'=>$price,'currency'=>$currency,'terms'=>$terms,'hash'=>$hash,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('contract_renewal');});}
    public function decide(string $id,string $action,array $input):array {return $this->atomic(function()use($id,$action,$input){$this->fields($input,['expected_hash','notes']);$r=$this->row('contract_renewals','renewal_id',$id);$c=$this->row('contracts','contract_id',$r['contract_id']);$this->mapped($r['client_id']);if((string)$c['client_id']!==(string)$r['client_id']||!empty($c['deleted_at']))throw HttpException::notFound();if(!$this->offerIntact($r)||$r['state']!=='SHARED'||$r['starts_on']<gmdate('Y-m-d')||!is_string($input['expected_hash']??null)||!hash_equals($r['offer_hash'],$input['expected_hash'])||!hash_equals($r['base_hash'],$this->fingerprint($c)))throw HttpException::conflict('Renewal changed, became stale or passed its start date.');$state=match($action){'accept'=>'ACCEPTED','decline'=>'DECLINED',default=>throw HttpException::notFound()};$this->db->execute('UPDATE contract_renewals SET state=:state,revision=revision+1,decided_by_user_id=:actor,decided_at=:now,decision_notes=:notes WHERE company_id=:company AND renewal_id=:id',['state'=>$state,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s'),'notes'=>$this->text($input['notes']??null,1000),'company'=>$this->company(),'id'=>$id]);$this->audit->record('contract_renewal',$action,$id);return ['state'=>$state];});}
    public function schedule(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['expected_revision']);$r=$this->row('contract_renewals','renewal_id',$id);if($r['state']!=='ACCEPTED'||$this->number($input['expected_revision']??null)!==(int)$r['revision'])throw HttpException::conflict('Choose the current accepted offer.');$c=$this->row('contracts','contract_id',$r['contract_id']);if(!$this->offerIntact($r)||!hash_equals($r['base_hash'],$this->fingerprint($c)))throw HttpException::conflict('Contract changed; prepare a new reviewed offer.');$this->db->execute("UPDATE contract_renewals SET state='SCHEDULED',revision=revision+1 WHERE company_id=:company AND renewal_id=:id",['company'=>$this->company(),'id'=>$id]);$this->audit->record('contract_renewal','scheduled',$id);return ['scheduled'=>true,'note'=>'The worker applies terms on the new start date, preserving the earlier term in history.'];});}
    public function applyDue():array {return $this->atomic(function(){$rows=$this->db->fetchAll("SELECT * FROM contract_renewals WHERE company_id=:company AND state='SCHEDULED' AND starts_on<=:today ORDER BY renewal_id LIMIT 100",['company'=>$this->company(),'today'=>gmdate('Y-m-d')]);$applied=0;$blocked=0;foreach($rows as$r){$c=$this->row('contracts','contract_id',$r['contract_id']);if(!$this->offerIntact($r)||!empty($c['deleted_at'])||!hash_equals($r['base_hash'],$this->fingerprint($c))){$this->db->execute("UPDATE contract_renewals SET state='BLOCKED',revision=revision+1 WHERE company_id=:company AND renewal_id=:id",['company'=>$this->company(),'id'=>$r['renewal_id']]);$blocked++;continue;}$meta=json_decode($c['shift_requirements_json']??'{}',true);if(!is_array($meta))$meta=[];$meta['currency']=$r['currency'];$meta['renewal_id']=$r['renewal_id'];$this->db->execute("UPDATE contracts SET start_date=:start,end_date=:end,monthly_value=:value,shift_requirements_json=:meta,status='ACTIVE',updated_by_user_id=:actor WHERE company_id=:company AND contract_id=:id",['start'=>$r['starts_on'],'end'=>$r['ends_on'],'value'=>number_format((int)$r['monthly_minor']/100,2,'.',''),'meta'=>json_encode($meta,JSON_THROW_ON_ERROR),'actor'=>$this->actor(),'company'=>$this->company(),'id'=>$r['contract_id']]);$after=$this->row('contracts','contract_id',$r['contract_id']);$this->db->execute('INSERT INTO contract_term_history(company_id,contract_id,renewal_id,before_json,after_json,applied_at) VALUES(:company,:contract,:renewal,:before,:after,:now)',['company'=>$this->company(),'contract'=>$r['contract_id'],'renewal'=>$r['renewal_id'],'before'=>json_encode($this->terms($c),JSON_THROW_ON_ERROR),'after'=>json_encode($this->terms($after),JSON_THROW_ON_ERROR),'now'=>gmdate('Y-m-d H:i:s')]);$this->db->execute("UPDATE contract_renewals SET state='APPLIED',revision=revision+1,applied_at=:now WHERE company_id=:company AND renewal_id=:id",['now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$r['renewal_id']]);$this->audit->record('contract_renewal','effective_terms_applied',(string)$r['renewal_id']);$applied++;}return ['applied'=>$applied,'blocked'=>$blocked];});}
    public function cancel(string $id):array {return $this->atomic(function()use($id){$r=$this->row('contract_renewals','renewal_id',$id);if(!in_array($r['state'],['SHARED','ACCEPTED','SCHEDULED','BLOCKED'],true))throw HttpException::conflict('This renewal cannot be cancelled.');$this->db->execute("UPDATE contract_renewals SET state='CANCELLED',revision=revision+1 WHERE company_id=:company AND renewal_id=:id",['company'=>$this->company(),'id'=>$id]);$this->audit->record('contract_renewal','cancelled',$id);return ['cancelled'=>true];});}
}
